//! Evaluation-domain helpers: primitive roots of unity, index → coset
//! point, FRI fold formula.
//!
//! Conventions:
//! - The LDE domain `D_lde` is the multiplicative subgroup of order
//!   `N = 2^log_lde` generated by `omega_lde`, a primitive `N`-th root
//!   of unity over Goldilocks.
//! - Index `k` in the LDE refers to the point `omega_lde^k` (no coset
//!   shift; v1 uses pure subgroup, not coset-FRI — extensible without
//!   wire breakage in v2).
//! - Binary FRI fold halves the domain each round: layer `i` has size
//!   `2^(log_lde - i)` and generator `omega_lde^(2^i)`.
//! - At layer `i`, index `k` and its sibling `k ^ (1 << (log_lde - i - 1))`
//!   correspond to points `x` and `-x` since `omega_lde^{2^i * (N/2)} = -1`.
//!
//! FRI fold rule (binary, no coset offset):
//!
//! Given layer-`i` evals `f_i(x) = a`, `f_i(-x) = b` and challenge `r`,
//! the next layer's eval at `x^2` is:
//!
//! ```text
//! f_{i+1}(x^2) = (a + b) / 2 + r * (a - b) / (2 * x)
//! ```
//!
//! which is the standard Plonky3/winterfell FRI fold.

use p3q_core::{P3qError, Result};
use p3q_field::{Field, Goldilocks};

/// Compute the LDE-domain generator `omega_lde = g^{(p-1) / 2^log_lde}`
/// where `g = 7` (Goldilocks generator).
pub fn lde_generator(log_lde: u32) -> Result<Goldilocks> {
    Goldilocks::two_adic_generator(log_lde).ok_or(P3qError::FieldOutOfRange)
}

/// Evaluate `omega_lde^k` for a public `k`. Uses square-and-multiply
/// on `k` directly rather than caching the entire domain (verifier
/// memory budget is tiny vs prover).
pub fn point_at_index(omega_lde: Goldilocks, k: u32) -> Goldilocks {
    omega_lde.pow(k as u64)
}

/// Sibling index for binary FRI fold at layer `i` over a domain of
/// log-size `log_layer`.
///
/// For layer-`i` domain of size `N_i = 2^log_layer`, paired evaluation
/// at index `k` is `(k, k ^ (N_i / 2))`.
///
/// Currently used only by the toy prover and tests; the production
/// verifier infers siblings from the wire encoding (each `LayerOpening`
/// carries an explicit `sibling` field), so this helper compiles only
/// under `test` or `feature = "prover"`.
#[cfg(any(test, feature = "prover"))]
#[inline]
pub fn sibling_index(k: u32, log_layer: u32) -> u32 {
    debug_assert!(log_layer >= 1);
    k ^ (1u32 << (log_layer - 1))
}

/// One FRI binary fold step.
///
/// `a` is the layer-`i` evaluation at `x = omega^k`, `b` is the eval
/// at `-x = omega^{k + N/2}`, `x` is the layer-`i` point, and `r` is
/// the round challenge. Returns the layer-`(i+1)` evaluation at `x^2`.
///
/// Reject (returns `FriVerification`) when `x = 0` (impossible in a
/// multiplicative subgroup, but guarded for defence-in-depth) or
/// `2*x` has no inverse.
pub fn fri_fold(a: Goldilocks, b: Goldilocks, x: Goldilocks, r: Goldilocks) -> Result<Goldilocks> {
    // (a + b) and (a - b) over the field.
    let sum = a + b;
    let diff = a - b;
    // 1 / 2 — Goldilocks has 2 invertible (P is odd).
    let two_inv = Goldilocks::from_u64(2)
        .inverse()
        .ok_or(P3qError::FieldOutOfRange)?;
    let half_sum = sum * two_inv;
    // (a - b) / (2 * x) = diff * (2 * x)^-1.
    let two_x = Goldilocks::from_u64(2) * x;
    let two_x_inv = two_x
        .inverse()
        .ok_or(P3qError::FriVerification("FRI fold: 2x is zero"))?;
    let half_diff_over_x = diff * two_x_inv;
    Ok(half_sum + r * half_diff_over_x)
}

/// Evaluate a polynomial in coefficient form at a point via Horner.
pub fn horner(coeffs: &[Goldilocks], x: Goldilocks) -> Goldilocks {
    let mut acc = Goldilocks::default();
    for &c in coeffs.iter().rev() {
        acc = acc * x + c;
    }
    acc
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn lde_generator_matches_two_adic() {
        for k in 1..=10 {
            let g = lde_generator(k).unwrap();
            assert_eq!(g, Goldilocks::two_adic_generator(k).unwrap());
        }
    }

    #[test]
    fn sibling_index_is_involutive() {
        for log in 1..=10u32 {
            for k in 0u32..(1 << log) {
                let s = sibling_index(k, log);
                assert_eq!(sibling_index(s, log), k);
                // and they differ by exactly N/2
                assert_eq!(k ^ s, 1u32 << (log - 1));
            }
        }
    }

    #[test]
    fn fri_fold_is_polynomial_decomposition() {
        // Take f(x) = c0 + c1*x + c2*x^2 + c3*x^3 over a domain of size 4,
        // and check that one binary fold produces a polynomial of degree
        // < 2 (i.e. constant + linear in x^2).
        // f(x)  = c0 + c1*x + c2*x^2 + c3*x^3
        // f(-x) = c0 - c1*x + c2*x^2 - c3*x^3
        // (f(x) + f(-x))/2 = c0 + c2*x^2   -> "even" part as polynomial in x^2
        // (f(x) - f(-x))/(2*x) = c1 + c3*x^2 -> "odd" part as polynomial in x^2
        // folded(y) = (c0 + c2*y) + r*(c1 + c3*y),  y = x^2.
        let c0 = Goldilocks::from_u64(7);
        let c1 = Goldilocks::from_u64(11);
        let c2 = Goldilocks::from_u64(13);
        let c3 = Goldilocks::from_u64(17);
        let r = Goldilocks::from_u64(19);

        // domain of size 4 -> omega = primitive 4th root
        let omega = Goldilocks::two_adic_generator(2).unwrap();
        let x = omega; // pick x = omega
        let nx = -x; // = omega * omega^2 = omega^3
        let f = |t: Goldilocks| -> Goldilocks { horner(&[c0, c1, c2, c3], t) };
        let a = f(x);
        let b = f(nx);
        let folded_eval = fri_fold(a, b, x, r).unwrap();

        let y = x * x;
        let expected = horner(&[c0 + r * c1, c2 + r * c3], y);
        assert_eq!(folded_eval, expected);
    }

    #[test]
    fn horner_matches_naive() {
        let coeffs: Vec<_> = (1u64..=5).map(Goldilocks::from_u64).collect();
        let x = Goldilocks::from_u64(3);
        let want = (1..=5u64).fold(Goldilocks::default(), |acc, i| {
            acc + Goldilocks::from_u64(i) * x.pow(i - 1)
        });
        assert_eq!(horner(&coeffs, x), want);
    }
}
